\label{lemma: disc via embs}
		Let $K$ be a number field with basis $B=\{b_1,\dots,b_n\}$ and let $\sigma_1,\dots,\sigma_n$ be the embeddings of $K$ into $\mathbb{C}$. Now let $M$ be the matrix  \[\left (\begin{matrix} \sigma_1(b_1) &\cdots& \sigma_1(b_n)\\ \vdots & & \vdots \\  \sigma_n(b_1) &\cdots& \sigma_n(b_n)
		\end{matrix} \right ).\] Then \[\Delta(B)=\det(M)^2.\]

\label{theorem:FLT facts}


		Let $p \geq 5$ be an prime number, $\zeta_p$ a $p$-th root of unity and $K=\mathbb{Q}(\zeta_p)$.  Assume that we have $x,y,z \in \mathbb{Z}$ with $\gcd(xyz,p)=1$ and such that \[x^p+y^p=z^p.\] 

		\begin{enumerate}
			\item We cannot have  \[x \equiv y \equiv -z \pmod p\] and, therefore, without loss of generality, we may assume \[x \not \equiv y \mod p.\]

			\item For $i \neq j$ we can write \[(\zeta_p^i-\zeta_p^j)=u(1-\zeta_p)\] with $u$ a unit in $\mathbb{Z}[\zeta_p]$. From this it follows that the ideals \[(x+y),(x+\zeta_py),(x+\zeta_p^2y),\dots,(x+\zeta_p^{p-1}y)\] are pairwise coprime. 

			\item Let $\alpha \in \mathbb{Z}[\zeta_p]$. Then $\alpha^p$ is congruent to an integer modulo $p$.

			\item Let $\alpha \in \mathbb{Z}[\zeta_p]$.   Suppose that $\alpha=a_0+a_1\zeta_p+\cdots+a_{p-1}\zeta_p^{p-1}$ with at least one $a_i=0$. Then there is an integer $n$ such that $\alpha/n \in \mathbb{Z}[\zeta_p]$, then $n$ divides each $a_i$. 


			\item   Let $i \in \{1,\dots,p-1\}.$ Suppose that $x+y\zeta_p^i=u \alpha^p$ with $u \in \mathbb{Z}[\zeta_p]^\times$ and $\alpha \in \mathbb{Z}[\zeta_p]$. By considering $x+y\zeta_p^i$ and its complex conjugate then there is an integer $k$ such that \[x+y\zeta_p^i-\zeta_p^{2k}x-\zeta_p^{2k-i}y \equiv 0 \pmod p.\]


		\end{enumerate}
